const items = $input.all();

const newLeads = items
  .filter(item => item.json.__source === 'new')
  .map(item => item.json);

const existingLeads = items
  .filter(item => item.json.__source === 'existing')
  .map(item => item.json);

function normalizeName(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\b(incorporated|inc|limited|ltd|llc|plc|corp|corporation|company|co)\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function getLinkedInSlug(lead) {
  const suppliedSlug = String(lead.linkedinSlug || '').trim();

  if (suppliedSlug) {
    return suppliedSlug.toLowerCase();
  }

  const url = String(
    lead.linkedinUrl || lead['LinkedIn URL'] || lead.LinkedIn || ''
  );

  const match = url.match(
    /(?:^|\/\/)(?:[a-z]{2,3}\.)?linkedin\.com\/company\/([^/?#]+)/i
  );

  return match ? match[1].toLowerCase() : '';
}

const existingNames = new Set();
const existingSlugs = new Set();

for (const lead of existingLeads) {
  const name = normalizeName(
    lead.companyName || lead['Company Name']
  );

  const slug = getLinkedInSlug(lead);

  if (name) existingNames.add(name);
  if (slug) existingSlugs.add(slug);
}

const seenNames = new Set();
const seenSlugs = new Set();
const output = [];

for (const lead of newLeads) {
  const name = normalizeName(
    lead.companyName || lead['Company Name']
  );

  const slug = getLinkedInSlug(lead);

  if (!name && !slug) continue;

  const alreadyExists =
    (name && existingNames.has(name)) ||
    (slug && existingSlugs.has(slug));

  const repeatedInBatch =
    (name && seenNames.has(name)) ||
    (slug && seenSlugs.has(slug));

  if (alreadyExists || repeatedInBatch) continue;

  if (name) seenNames.add(name);
  if (slug) seenSlugs.add(slug);

  output.push({
    json: {
      ...lead,
      __source: 'new'
    }
  });
}

return output;

const lead=$input.item.json||{};
const company=String(lead.companyName||'').trim();
const country=String(lead.country||'').trim();
const industry=String(lead.industry||'').trim();
const query=`"${company}" ${country!=='Unknown'?`"${country}"`:''} ${industry} (revenue OR "annual revenue" OR "estimated revenue" OR founded OR "year founded" OR hiring OR careers OR expansion OR growth)`;
return {json:{...lead,budgetResearchQuery:query,maxResults:5}};

const lead=$('Generate Lightweight Budget Signal Query').item.json||{};
const data=$input.item.json||{};
const results=Array.isArray(data.results)?data.results:[];
const company=String(lead.companyName||'').trim();
const norm=s=>String(s||'').toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
const companyNorm=norm(company);
const credibleDomains=/crunchbase\.com|growjo\.com|getlatka\.com|zoominfo\.com|pitchbook\.com|tracxn\.com|dealroom\.co|cbinsights\.com|craft\.co|companiesmarketcap\.com|forbes\.com|bloomberg\.com|reuters\.com|techcrunch\.com|businesswire\.com|prnewswire\.com|inc\.com|ft\.com|wsj\.com|sifted\.eu|thenextweb\.com|venturebeat\.com|linkedin\.com\/company/i;
function mentionsCompany(t){const n=norm(t);return companyNorm.length>=4&&(n.includes(companyNorm)||companyNorm.split(' ').filter(w=>w.length>3).every(w=>n.includes(w)));}
const evidence=[]; let revenueM=null, foundedYear=null, hiring=false, hiringStrong=false, growth=false;
const currentYear=new Date().getFullYear();
for(const r of results){
 const title=String(r.title||'');const content=String(r.content||r.raw_content||'');const url=String(r.url||'');const text=`${title}\n${content}`;
 if(!mentionsCompany(text)) continue;
 const sourceDomain=(url.match(/^https?:\/\/([^/]+)/i)||[])[1]||'';
 const credible=credibleDomains.test(url)||/annual report|press release|funding announcement|investor/i.test(title+' '+content);
 // Revenue is only scored when source quality is plausibly credible and the text explicitly ties the figure to revenue.
 if(revenueM===null&&credible&&/revenue|turnover|sales/i.test(text)){
  let m=text.match(/(?:annual revenue|estimated revenue|revenue estimate|revenue|turnover|annual sales)[^$€£\n]{0,45}(?:US\$|USD\s*|\$)\s*([\d,.]+)\s*(billion|bn|million|mn|m|b|k)?/i);
  if(!m) m=text.match(/(?:US\$|\$)\s*([\d,.]+)\s*(billion|bn|million|mn|m|b|k)?[^\n]{0,35}(?:annual revenue|estimated revenue|revenue|turnover|sales)/i);
  if(m){let n=Number(String(m[1]).replace(/,/g,''));const unit=String(m[2]||'').toLowerCase();if(['billion','bn','b'].includes(unit))n*=1000;else if(['k'].includes(unit))n/=1000; if(Number.isFinite(n)&&n>0&&n<1000000){revenueM=n;evidence.push(`Revenue evidence approximately $${n}M (${sourceDomain||'source unlabelled'})`);}}
 }
 let fm=text.match(/(?:founded|established|founded in|established in|year founded|founded year|since)\s*(?:in\s*)?(19\d{2}|20[0-2]\d)\b/i);
 if(!fm) fm=text.match(/(?:company was founded|founded by[^.]{0,100}\bin\s+)(19\d{2}|20[0-2]\d)\b/i);
 if(foundedYear===null&&fm){const y=Number(fm[1]);if(y>=1950&&y<=currentYear){foundedYear=y;evidence.push(`Founded/established ${y} (source: ${sourceDomain||'unlabelled'})`);}}
 if(/careers|open positions|we are hiring|join our team|job openings|current openings|multiple vacancies|open roles/i.test(text)){hiring=true;if(/multiple vacancies|\b\d{2,}\s+(?:open|current)?\s*(?:roles|positions|jobs|vacancies)|hiring across|actively hiring|rapidly hiring/i.test(text))hiringStrong=true;}
 if(/expanded into|expansion|grew by|growth of|year.over.year growth|raised a series|new office|opened an office|scaling (?:the )?team|rapid growth|customer growth|headcount growth/i.test(text)){growth=true;}
 if(evidence.length<8&&(/founded|revenue|hiring|growth|expansion|employees/i.test(text))) evidence.push(`${title||sourceDomain}: ${content.slice(0,240).replace(/\s+/g,' ').trim()}`);
}
let score=0;const reasons=[];
const min=Number(lead.employeeCountMin),max=Number(lead.employeeCountMax);
if(Number.isFinite(min)&&Number.isFinite(max)){
 const mid=(min+max)/2;
 if(mid>=125){score+=25;reasons.push(`employee scale ${lead.companySize} (+25)`)}
 else if(mid>=51){score+=18;reasons.push(`employee scale ${lead.companySize} (+18)`)}
 else {score+=8;reasons.push(`employee scale ${lead.companySize} (+8)`)}
}
if(revenueM!==null){if(revenueM>=25){score+=30;reasons.push('credible revenue signal ≥$25M (+30)')}else if(revenueM>=10){score+=24;reasons.push('credible revenue signal $10M–$24M (+24)')}else if(revenueM>=2){score+=16;reasons.push('credible revenue signal $2M–$9M (+16)')}else{score+=6;reasons.push('credible revenue signal below $2M (+6)')}}
if(growth){score+=10;reasons.push('growth/expansion signal (+10)')}
if(hiringStrong){score+=10;reasons.push('strong hiring signal (+10)')}else if(hiring){score+=5;reasons.push('hiring/careers signal (+5)')}
if(foundedYear!==null){const years=Math.max(0,currentYear-foundedYear);if(years>=10){score+=15;reasons.push(`${years} years operating (+15)`)}else if(years>=6){score+=10;reasons.push(`${years} years operating (+10)`)}else if(years>=3){score+=6;reasons.push(`${years} years operating (+6)`)}else{score+=3;reasons.push(`${years} years operating (+3)`)}}
let label='Low';if(score>=65)label='High';else if(score>=40)label='Medium';
const confidence=(revenueM!==null&&foundedYear!==null&&(growth||hiring))?'High':((revenueM!==null||foundedYear!==null||growth||hiring)?'Medium':'Low');
const basis=reasons.length?reasons.join('; '):'Only the LinkedIn employee-size signal was available';
const evidenceText=evidence.slice(0,5).join(' | ');
const budgetFit=`${label} (${score}/100; ${confidence} evidence confidence) — ${basis}`;
return {json:{
 companyName:lead.companyName,linkedinUrl:lead.linkedinUrl,companySize:lead.companySize,country:lead.country,industry:lead.industry,
 budgetFit,budgetScore:score,budgetConfidence:confidence,budgetEvidence:evidenceText||'No reliable company-specific revenue, growth/hiring, or founding-year evidence found.',
 targetRegion:lead.targetRegion,regionPriority:lead.regionPriority,sizeEvidence:lead.sizeEvidence
}};

const items = $input.all();
const queryItems = $('Generate Targeted Discovery Queries').all();

const seen = new Set();
const leads = [];

function clean(v) {
  return String(v || '').replace(/\s+/g, ' ').trim();
}

function slugFromUrl(url) {
  const m = String(url || '').match(
    /(?:^|\/\/)(?:[a-z]{2,3}\.)?linkedin\.com\/company\/([^/?#]+)/i
  );

  return m ? m[1].replace(/\/$/, '') : '';
}

function industryFrom(text) {
  const t = String(text || '').toLowerCase();

  const groups = [
    [
      'SaaS / Software',
      /\bsaas\b|software development|software company|software platform|cloud platform|developer tools|enterprise software|embedded software/
    ],
    [
      'IT Services / Consulting',
      /it services|information technology|technology consulting|managed services|systems integrator|it consulting/
    ],
    [
      'Marketing / Digital Agency',
      /marketing agency|digital agency|growth marketing|advertising agency|performance marketing|digital marketing/
    ],
    [
      'Design / Product Agency',
      /design agency|product design|ux design|user experience|creative studio|product studio/
    ],
    [
      'Fintech',
      /fintech|financial technology|payments platform|financial software|digital banking/
    ]
  ];

  for (const [label, re] of groups) {
    if (re.test(t)) return label;
  }

  return 'Unknown';
}

function sizeFrom(text) {
  const s = String(text || '').replace(/\r/g, '\n');

  // Prefer a definite employee count when explicitly labelled.
  const exactPatterns = [
    /Employees\s*[\n\s]*[-•]?\s*Now\s*:\s*(\d{1,5})\b/i,
    /\bcompany employees?\s*[:\n-]*\s*(\d{1,5})\b/i,
    /\bnumber of employees\s*[:\n-]*\s*(\d{1,5})\b/i
  ];

  for (const re of exactPatterns) {
    const m = s.match(re);
    if (!m) continue;

    const n = Number(m[1]);
    if (n < 1) continue;

    return {
      label: String(n),
      min: n,
      max: n,
      exact: true
    };
  }

  // If no definite count is found, accept a stated employee-size band.
  const bandPatterns = [
    /\b(\d{1,5})\s*[-–—]\s*(\d{1,5})\s+employees?\b/i,
    /company size\s*[:\n-]*\s*(\d{1,5})\s*[-–—]\s*(\d{1,5})\b/i
  ];

  for (const re of bandPatterns) {
    const m = s.match(re);
    if (!m) continue;

    const min = Number(m[1]);
    const max = Number(m[2]);

    if (min < 1 || max < min) continue;

    const context = s.slice(
      Math.max(0, m.index - 150),
      Math.min(s.length, m.index + m[0].length + 100)
    );

    // Avoid mistaking customer or user counts for employee counts.
    if (
      /customers?|clients?|users?|target market|served businesses/i.test(context)
    ) {
      continue;
    }

    return {
      label: `${min}-${max}`,
      min,
      max,
      exact: false
    };
  }

  return null;
}

function countryFrom(text) {
  const s = String(text || '');

  const m = s.match(
    /(?:headquarters|headquartered|based in|location)\s*[:\-]?\s*([^\n.;]{2,100})/i
  );

  const context = m ? m[1] : s;
  const t = (context + ' ' + s.slice(0, 500)).toLowerCase();

  const states = /\b(alabama|alaska|arizona|arkansas|california|colorado|connecticut|delaware|florida|georgia|hawaii|idaho|illinois|indiana|iowa|kansas|kentucky|louisiana|maine|maryland|massachusetts|michigan|minnesota|mississippi|missouri|montana|nebraska|nevada|new hampshire|new jersey|new mexico|new york|north carolina|north dakota|ohio|oklahoma|oregon|pennsylvania|rhode island|south carolina|south dakota|tennessee|texas|utah|vermont|virginia|washington|west virginia|wisconsin|wyoming|united states|\busa\b|u\.s\.a\.|\bus\b)\b/;

  if (states.test(t)) return 'United States';

  const countries = [
    ['United Arab Emirates', /united arab emirates|\buae\b|dubai|abu dhabi/],
    ['United Kingdom', /united kingdom|\buk\b|england|scotland|wales|london|manchester/],
    ['Germany', /germany|berlin|munich|hamburg/],
    ['Ireland', /ireland|dublin/],
    ['Netherlands', /netherlands|amsterdam/],
    ['France', /france|paris/],
    ['Spain', /spain|madrid|barcelona/],
    ['Italy', /italy|milan|rome/],
    ['Portugal', /portugal|lisbon/],
    ['Sweden', /sweden|stockholm/],
    ['Norway', /norway|oslo/],
    ['Denmark', /denmark|copenhagen/],
    ['Finland', /finland|helsinki/],
    ['Estonia', /estonia|tallinn/],
    ['Poland', /poland|warsaw/],
    ['Switzerland', /switzerland|zurich/],
    ['Austria', /austria|vienna/],
    ['Belgium', /belgium|brussels/],
    ['Czechia', /czechia|czech republic|prague/],
    ['Romania', /romania|bucharest/],
    ['Lithuania', /lithuania|vilnius/],
    ['Latvia', /latvia|riga/],
    ['Greece', /greece|athens/],
    ['Ukraine', /ukraine|kyiv/],
    ['Singapore', /singapore/],
    ['India', /india|bengaluru|bangalore|mumbai|new delhi|hyderabad/],
    ['Japan', /japan|tokyo/],
    ['South Korea', /south korea|seoul/],
    ['Hong Kong', /hong kong/],
    ['Taiwan', /taiwan|taipei/],
    ['Malaysia', /malaysia|kuala lumpur/],
    ['Philippines', /philippines|manila/],
    ['Indonesia', /indonesia|jakarta/],
    ['Thailand', /thailand|bangkok/],
    ['Vietnam', /vietnam|ho chi minh/],
    ['China', /china|shanghai|beijing|shenzhen/],
    ['Australia', /australia|sydney|melbourne/]
  ];

  for (const [name, re] of countries) {
    if (re.test(t)) return name;
  }

  return 'Unknown';
}

function regionOf(country, fallback) {
  if (country === 'United States') return 'USA';
  if (country === 'United Arab Emirates') return 'UAE';

  if ([
    'United Kingdom', 'Germany', 'Ireland', 'Netherlands', 'France',
    'Spain', 'Italy', 'Portugal', 'Sweden', 'Norway', 'Denmark',
    'Finland', 'Estonia', 'Poland', 'Switzerland', 'Austria',
    'Belgium', 'Czechia', 'Romania', 'Lithuania', 'Latvia',
    'Greece', 'Ukraine'
  ].includes(country)) {
    return 'Europe';
  }

  if ([
    'Singapore', 'India', 'Japan', 'South Korea', 'Hong Kong',
    'Taiwan', 'Malaysia', 'Philippines', 'Indonesia', 'Thailand',
    'Vietnam', 'China', 'Australia'
  ].includes(country)) {
    return 'Asia';
  }

  return fallback || 'Unknown';
}

const rank = {
  USA: 1,
  Europe: 2,
  Asia: 3,
  UAE: 4,
  Unknown: 5
};

for (let i = 0; i < items.length; i++) {
  const data = items[i].json || {};
  const query = queryItems[i]?.json || {};

  const results = Array.isArray(data.results) ? data.results : [];

  for (const r of results) {
    const url = clean(r.url);
    const slug = slugFromUrl(url);

    if (!slug) continue;

    const title = clean(r.title);
    const content = clean(
      r.content || r.description || r.raw_content || ''
    );

    const combined = `${title}\n${content}`;

    let name = title
      .replace(/\s*[|–-]\s*LinkedIn.*$/i, '')
      .replace(/\s*[|–-]\s*LinkedIn$/i, '')
      .trim();

    if (!name || /^(linkedin|company)$/i.test(name)) {
      name = slug
        .replace(/-/g, ' ')
        .replace(/\b\w/g, c => c.toUpperCase());
    }

    const size = sizeFrom(combined);
    if (!size) continue;

    const industry = industryFrom(combined);
    if (industry === 'Unknown') continue;

    const country = countryFrom(combined);
    const region = regionOf(country, query.region);

    const key = slug.toLowerCase();

    if (seen.has(key)) continue;
    seen.add(key);

    leads.push({
      companyName: name,
      linkedinUrl: url,
      linkedinSlug: slug,
      companySize: size.label,
      employeeCountMin: size.min,
      employeeCountMax: size.max,
      country,
      industry,
      targetRegion: region,
      regionPriority: rank[region] || 5,
      companyDescription: content.slice(0, 900),
      __source: 'new',
      sizeEvidence: size.exact
        ? 'Exact employee count'
        : 'Employee-size band',
      discoveryQuery: query.query || ''
    });
  }
}

leads.sort(
  (a, b) =>
    (a.regionPriority - b.regionPriority) ||
    (b.employeeCountMax - a.employeeCountMax) ||
    a.companyName.localeCompare(b.companyName)
);

return leads.map(json => ({ json }));
